INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('0d846a1c-e1fe-457b-a8c0-caf6e4ce562f', 'ocds-b5fd17-c10468de-1b42-4e83-8740-03eaa23edf61', 'CA17680 - North Warwickshire & South Leicestershire College - Maintenance, Servicing & Monitoring of Fire & Intruder Systems', 'North Warwickshire & South Leicestershire College requires one or more supplier to fulfil their Maintenance, Servicing & Monitoring of Fire & Intruder Systems requirement.  

