INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('ff622b55-09e0-45a3-b349-6488841371d8', 'ocds-b5fd17-e334ff6d-4e82-4e0b-b65b-36d272e14455', 'Embedding Innovation and Commercialisation', 'RAICo seeks to appoint a suitably qualified external delivery partner to design and deliver a tailored Embedding Innovation and Commercialisation Programme for a selected internal cohort.  The programme will build commercial awareness, entrepreneurial thinking, and the practical skills required to progress innovation initiatives into viable business propositions aligned with RAICo''s strategic objectives', NULL, '7375be37-dc23-4c05-b0e9-2201815d8931', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 125000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/6f7c8868-069d-4195-b808-9a8cd3b976a4', NULL, NULL, NULL, ARRAY['Training services', 'UK', 'Contracts Finder'], '2026-05-05', '2026-04-30', '675337a1199e2b9c73fd0235f928412f8b6f22523bbf670c735613219fe862a2') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('9b2c56cc-4357-4d14-a8b7-365e62be0f9e', 'ocds-b5fd17-f682f7ef-3ccb-4fce-ab39-bd1cf20f32ad', '5051/EFM/RH - Edgar Allen House, IT Alterations', '5051/EFM/RH - Edgar Allen House, IT Alterations
You are invited to tender for the above titled project. This is a open tender process following University process. 
The Invitation to Tender (ITT) can be downloaded by registering and expressing your interest on the University`s e-tendering system https://in-tendhost.co.uk/Sheffield. 
This project comprises the refurbishment of the second and third floor of the Edgar Allen House, within the University of Sheffield Campus.  The aim of the project to undertake layout alterations, M&E upgrades, improvements to the existing WC facilities and fibre connections.
The Invitation to Tender (ITT) can be downloaded by registering and expressing your interest on the University`s e-tendering system https://in-tendhost.co.uk/Sheffield. The tender documents provide full information, which will be sent to you once you have expressed your interest. If you have any questions or comments in relation to this tender they must be submitted via the In-tend System, this can be accessed at https://in-tendhost.co.uk/Sheffield. Completed tenders must be returned through the same e-tendering system.
Site visits are Scheduled for Monday 18th May 2026 to provide an opportunity for tenderer''s to further ascertain the nature of the site, access thereto and all local conditions and restrictions likely to affect the execution of the Works. These are not mandatory.  Arrangements for site visits are to be made by Contacting William Bowen, Castle Owen Construction & Property Consultants, (w.bowen@castleowen.com, 0114 233116). We inform bidders that we withhold the right to change the date and/or schedule further site visits if required.', NULL, 'f4c745c0-30b4-48c4-8379-40ad2304cdc3', (SELECT id FROM project_categories WHERE name = 'GIS'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 839149, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/c9c29765-d962-49cb-bb89-bf6a6dc8ae7e', NULL, NULL, NULL, ARRAY['Overhaul and refurbishment work', 'UK', 'Contracts Finder'], '2026-05-29', '2026-04-30', 'b4a2db1c6b1ae95bc4c246334a0202698192f542e97a856bbbda5fcf8ec1ce5b') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('32d9669b-40c9-4645-9bc0-2e6082094f52', 'ocds-b5fd17-1a04b77c-c544-4ce3-8dae-eaee6727b8e3', 'A66 Northern Trans-Pennine (NTP) - Temporary Vehicle Restraint System', 'Kier Transportation intends to engage experienced and qualified contractors to undertake works associated with Temporary Vehicle Restraint System across A66 NTP. The appointed contractor will be responsible for providing a reliable and professional security presence to protect our assets, property, personnel, and visitors outside of standard working hours. 

We will use the Build UK Common Assessment Criteria (CAS) to ensure a consistent minimum business competence. If your company possesses necessary qualifications and is interested in bidding for this project, please email infrastructure.procurement@kier.co.uk  with your company''s portfolio, relevant experience, and references for further evaluation.', NULL, '1ab94104-c430-4214-918c-4ceaba391c74', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 50000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/0ee6fccf-d79f-43ed-a2ab-463f16574a25', NULL, NULL, NULL, ARRAY['Road barriers', 'UK', 'Contracts Finder'], '2026-05-31', '2026-05-01', 'ba747ea44071667c0d58880deb721407f81e3c4575f3b82f4195feb10becb310') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('ca6f58b2-0096-46f1-ad60-6c986b570933', 'ocds-b5fd17-38a279ab-d69c-4ca1-92da-5b297f058f9d', 'Temporary Works Designer (Track Design Railhead)', 'To construct the main works, the (Ferrovial BAM JV) Track Systems Contractor (FBRS) will develop and operate temporary railheads/connections to the Network Rail infrastructure, to meet the construction logistics requirements for material deliveries by rail and support the requirements of other Railway System Contractors from the Alliance. These railheads/connections require temporary rail track works that will not form part of the final permanent works.
      
      The Temporary Railhead designs required are located at: 
      
      •	West Ruislip (Copthall) Temporary Railhead 
      •	Chiltern South Temporary Railhead 
      •	Berkswell Temporary Railhead 
      •	Washwood Heath Temporary Connection 
      
      The Consultant shall achieve integration and coordination between temporary and permanent works design, liaising with the Permanent Works Designer.
      
      The scope of this required design works are as follows - Track layout and geometry, Track, Track drainage, LWR and S&C hardstanding areas, gantry foundations.
      
      
      Potential mobilization start (soft start) in September 2026 - then estimated full start February 2027.', NULL, '8cceb3cd-811f-4d5a-8ae7-f77ddb465efe', (SELECT id FROM project_categories WHERE name = 'GIS'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 2500000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/81a4ff89-4284-48d5-91e5-4b8dedd0ec22', NULL, NULL, NULL, ARRAY['Civil engineering consultancy services', 'UK', 'Contracts Finder'], '2026-05-15', '2026-05-01', '030d580319e60e835f144cc9bf704b6484c0c1950e70fbd609a6498c0d0c201f') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('85e4e088-414f-49d2-b2e7-351087b6a8f4', 'ocds-b5fd17-48e9a80f-ff6d-47fb-89a7-a74e0d042a6c', 'CA17733 - ITT 13/2026 - PEACEPLUS PP2021 - Ballyhornan Community Association 3G Pitch Spectator Seating', 'Applications are invited from Contractors, under the terms of the NEC4 ECSC Short Contract, who wish to be considered for inclusion on a Select List for the following PEACEPLUS project:  Ballyhornan Community Association - Spectator Seating PP2021: Supply and installation of a 50 seater spectator stand to the side of 3G Pitch at Ballyhornan Community Association site. 

A shortlist of Supplier''s will be compiled (Randomly Generated if over six Applicants) and invited to submit bids for the project. The works will be for Furniture (Sports & Leisure) 45421153-1, Civil Engineering - 45200000-9, Sports + Playground surfaces - 45112720-8, Fencing (Sports & Playgrounds) - 45342000-6, Sports Equipment Installation - 45212200-8 for a period of 4 weeks and will commence not before June 2026.

