INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('b744eeb1-5d10-4f2c-b399-34bf377953fe', 'ocds-b5fd17-5f24015d-f7eb-49a6-904d-1a1d7050a575', 'Temporary Works Designer - Framework', 'To construct the main works, the (Ferrovial BAM JV) Track Systems Contractor (FBRS) will develop and operate various compounds (including railheads) along the route, to meet the construction logistics requirements of FBRS and also support the requirements of other Railway System Contractors from the Alliance. These compounds will require temporary works that will not form part of the final permanent works.
       
      The number and location of the compounds to be used are still to be confirmed at this stage:
       
      The Consultant shall achieve integration and coordination between temporary and permanent works design, liaising with the Permanent Works Designer where required.
       
      Examples of the scope of this required design works are as follows (but not limited to) within compounds and railheads-
      
      •Temporary site buildings and offices
      •Temporary utilities & services
      •Temporary roadways and hardstandings
      •Temporary site drainage systems
      •Fencing
      •Lighting & Security systems
      
      
      Note: the scope does not include any design of Track layouts and geometry, Track, Track drainage, LWR and S&C hardstanding areas, associated gantry foundations within the railheads.
      
      Potential mobilization start (soft start) in October 2026 - then estimated full start February 2027.', NULL, '8cceb3cd-811f-4d5a-8ae7-f77ddb465efe', (SELECT id FROM project_categories WHERE name = 'GIS'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 1000000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/38570d6c-6d21-45f0-ac5f-d2ca25177616', NULL, NULL, NULL, ARRAY['Civil engineering consultancy services', 'UK', 'Contracts Finder'], '2026-05-15', '2026-05-01', '3d8a65366a6a474c5f643206629c1b0e48e482e39eed1206f718a3545d677f64') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('d5355fcb-6a3b-4225-a23c-f520a81a79d9', 'ocds-b5fd17-77c15fe4-9a08-4d3a-b501-2b860d581073', 'A66 Northern Trans-Pennine(NTP) - Temporary Road Marking', 'Kier Transportation intends to engage experienced and qualified contractors to undertake works associated with Temporary road Markings required for traffic management along the A66 NTP. The appointed contractor will be responsible for providing a reliable and professional security presence to protect our assets, property, personnel, and visitors outside of standard working hours. 

We will use the Build UK Common Assessment Criteria (CAS) to ensure a consistent minimum business competence. If your company possesses necessary qualifications and is interested in bidding for this project, please email infrastructure.procurement@kier.co.uk  with your company''s portfolio, relevant experience, and references for further evaluation.', NULL, '1ab94104-c430-4214-918c-4ceaba391c74', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 15000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/6381d3f9-697a-4fd2-a63e-5f75a5a5d31a', NULL, NULL, NULL, ARRAY['Road markings', 'UK', 'Contracts Finder'], '2026-05-31', '2026-05-01', '8a72a45bff69868e3f3839c43f3d84faed9554bdd0379718bfd22510269c2a68') ON CONFLICT DO NOTHING;
