INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('3dad229f-d98d-4908-b32c-dfcf1896b2a7', 'ocds-b5fd17-66f07be4-c35b-42ac-ad38-c6470a05061d', 'GB-Plymouth: OPA T827 OFD Thanckes, Out of service Inspection of 3 off Nato Tanks (T29, T30, T33)', 'OPA T827. To carry out Non-Destructive Testing (NDT) in tanks 029, 30,33 located at Thanckes in accordance with the OPA - Storage Tank Out of Service Inspection document OPA-ST-5101.', NULL, '9584c974-6631-4d60-b778-39455ad136c0', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 100000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/816f1e3c-1640-4856-934a-07dc9100f916', NULL, NULL, NULL, ARRAY['Technical inspection services of engineering structures', 'UK', 'Contracts Finder'], '2026-06-04', '2026-05-08', 'fb08ce336a94fdfb48091b6a5630ecbf9bbcbb4cfc75c400ee21b0b98b1d50da') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('685a4cde-9b44-4ddd-8b31-76e4df53cdbf', 'ocds-b5fd17-8b5f2aad-ba49-4873-824d-b9218f9c04cf', 'Development and Integration of a Unified Data System for Sustainable Forest Management', 'The Multistakeholder Forestry Programme (MFP) is a long-term bilateral cooperation between Indonesia and the UK (since 2000) aimed at strengthening forest governance, tackling illegal logging, and improving livelihoods. Now in Phase 5 (launched 2026), it promotes sustainable management, timber legality (SVLK), and community-based forestry to support Indonesia''s FOLU Net Sink 2030 target. 

Through this Two-Stage Open Tender process, the Multistakeholder Forestry Programme Phase 5 (MFP5) seeks to find a qualified technology service provider for the development of an integrated and reliable Forest Data Governance System. The initiative aims to improve data integration, consistency, and accessibility across existing systems, and to support analysis, monitoring, and decision-making through a comprehensive dashboard reflecting key forest management processes. 

The budget for this work is estimated to be in the range of IDR 2.750.000.000 to IDR 3.500.000.000.  Interested organizations are invited to submit an Expressions of Interest (EOI) demonstrating relevant technical capability and organizational capacity to deliver the services. The closing date for EOI submission is 18th May 2026, 1:00 PM, Jakarta Time. The full information is provided in the Term of Reference (TOR), available in English and Bahasa Indonesia.', NULL, 'c6f70188-ab70-4e8d-a8a6-f504f6ead130', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 148000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/496c805c-8b8c-475b-80b6-1e64da071cd4', NULL, NULL, NULL, ARRAY['Agricultural, farming, fishing, forestry and related products', 'UK', 'Contracts Finder'], '2026-05-18', '2026-05-08', 'b3edc52be27959129b56f3776c67c8d03e44317d67ea773c767bc9a991e7357b') ON CONFLICT DO NOTHING;
