INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('f1ece697-5c19-4635-a073-5d95a045088a', 'ocds-b5fd17-54c7c7bf-ca13-4d06-8a30-8c19ae4a63ad', 'MARITIME & COASTGUARD AGENCY (MCA) - HIGHLANDS & ISLANDS MODULAR CRS FACILITIES UPGRADE PROJECT', 'The Maritime and Coastguard Agency (MCA) is seeking an experienced and innovative supplier to design, deliver and install modular buildings at remote Coastal Rescue Station (CRS) locations across the UK. These buildings will enhance welfare and operational facilities for His Majesty''s Coastguard (HMCG) teams.', NULL, '56ec195c-c66a-42b6-974f-303e4413738a', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 1000000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/22f58f89-de05-457a-b8db-736fda64637a', NULL, NULL, NULL, ARRAY['Construction work', 'UK', 'Contracts Finder'], '2026-06-02', '2026-05-12', '1bf20dba3df3161924f4441ec2283a7fb5e04c654d16402b2225dc644f366037') ON CONFLICT DO NOTHING;
