INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('a8cc222a-90e1-4a76-8b59-b335322e131a', 'ocds-b5fd17-8dc098de-9a50-45d2-b393-924ef69d1926', 'MCC - Refurbishment', 'The works include internal strip-out, removal of the existing stage, new suspended ceiling to the main hall, new foyer ceiling, electrical and LED lighting works, review of the existing distribution board and supply capacity, ventilation considerations, treatment of high-level windows, new LVT flooring to the main hall, new foyer flooring, associated woodwork and ironmongery, new fire door access to Main Street, new AV system, creation of a patio area with low-level fencing, coordination with the Council''s security contractor for CCTV and alarms, new sockets and data points, full air conditioning / space heating design for the main hall, removal of redundant DEC heaters, replacement foyer electric heating, internal decoration, commissioning, certification, as-built drawings, controls information and handover.

The facility is an occupied community building. Tenderers must allow for safe working, public protection, CDM 2015 compliance, asbestos risk management, Building Regulations compliance and Sport England evidence requirements.

Tenderers must submit a complete tender response in accordance with the Invitation to Tender documents by the stated deadline.', NULL, 'ec43722e-4673-4350-ae63-62382c3596ad', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 115000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/662d1ab9-4951-42d7-bba0-e6fe4dcb120e', NULL, NULL, NULL, ARRAY['Audio-visual equipment', 'UK', 'Contracts Finder'], '2026-06-18', '2026-05-14', '59dce8eeda217d72b0e9faaee0246a959b5fd1d10eed90aa7e7a4de71cc183da') ON CONFLICT DO NOTHING;
