INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('764e6baf-bfc4-4095-91d5-4fd96dace295', 'ocds-b5fd17-6e3e3ee9-8753-406d-8e44-04db00ef052d', 'RA356995 - Campus WiFi Refresh', 'PLEASE ATTACH A QUOTE. (Include any other considerations to be made such as any services or works that would be required that are not mentioned in this.)

