INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('63b6930a-6c99-4b9c-9b7a-0d72db3301d2', 'ocds-b5fd17-8926ac8d-9bc0-47a1-8a68-f9618678c3ea', 'St Oswald''s Church, Coney Hill: To prepare for a Sustainable Future', 'The proposed work is as follows: 

•	Rainwater goods - repairs, replacement/refurbishment
•	Roof Repairs - repairs to clay tiling, timber soffit and South Aisle lead abutments. 
•	Vestry Parapet Repairs - dismantling and rebuilding parapet with lead damp proof course.
•	North Chimney stack - dismantle and roof repairs.
•	External repointing - to Chancel and isolated areas elsewhere.
•	Internal plaster repairs and redecoration - to Chancel and Vestry.
•	External doors - repairs and redecoration.
•	New glazed entrance doors.
•	New lighting installation
•	New heating installation
•	External landscaping (access improvements)

To apply please email office@arnoldbartosch.co.uk

The contract will only be awarded if the church is successful with its Delivery Phase grant application to the National Lottery Heritage Fund.', NULL, 'e49780c2-270b-4548-b21a-dcfa2746b17a', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 500000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/475de3d5-764b-4f41-8c9f-053cf1afdff8', NULL, NULL, NULL, ARRAY['Church construction work', 'UK', 'Contracts Finder'], '2026-06-01', '2026-05-26', '7b5a5fb50656fe8ac637777c9cf0bf9c8b930fa58acaf0ffa302ec2da89aaa24') ON CONFLICT DO NOTHING;
