INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('c99e8b56-1899-4adb-a1de-174be621e554', 'ocds-b5fd17-9ba1c494-c868-4466-b328-bd78f216e66e', 'EKFB JV - Highways Works NC2A', 'NC2A is the North Chilterns to Aylesbury section of C23, a part of the HS2 project managed by the EKFB Joint Venture. 
      
      We are seeking a specialist subcontractor to undertake the following works within the NC2A section: 
      
      The Subcontract Works includes for the provision of all management, labour, materials, plant and equipment, supervision, and other resources necessary and ancillary to safely complete the construction and handover of Highways/ footpaths works, as described in the specifications, drawings, HS2 standards Requirements and local authority specifications. The Subcontractor will be responsible for the temporary works design and temporary works construction as further detailed in this document.
      The subcontractor will be responsible for all permanent and temporary works relating to the  Highways realignment unless otherwise excluded. The works included as part of this scope to be delivered by the subcontractor are:
      -	Site clearance including Removal of existing drainage, kerbs, footpath, highway pavement, verges within permanent design location.
      -	Earthworks including excavation to formation, soft spot treatment if required.
      -	Drainage system, including temporary excavations, supply and installation of chambers, gullies, headwalls, carrier drains, filter and fin drains, fin drains, ditches, hydro brake system, non-return valve connection to existing drainage systems.
      -	Service ducts: including supply and installation of service ducts, connections and chambers.
      -	Road formation (asphalt surfacing by others): this includes supply and installation of geotextile separation materials highways and footways kerbs. Installation of capping and subbase layers
      
      
      Please express your interest within this package.', NULL, 'c72a530a-c922-4b53-8ae4-8787ffd8534d', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 500000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/1d61fc20-e220-40a0-b5ce-d9c847425012', NULL, NULL, NULL, ARRAY['Construction work for highways', 'UK', 'Contracts Finder'], '2026-06-05', '2026-05-29', '684856f3d6625198198b6b51c84c6bec8f683496bfabeba5c172b7e7ba9180a8') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('883820c5-46a6-41d4-9b28-ce3adcc24469', 'ocds-b5fd17-b024463f-5f12-4380-8a20-30dce7ea2d90', 'Perseid Lower School KS2 Fencing Works', 'Works involve installation of largely new weldmesh fencing to the KS2 playground and rear exits of Classrooms inc door access controls, in order to provide segregation. 
Programme length 3 weeks to take place 3rd to 23rd August ''2026.
Please note all queries, correspondence and tender submissions must be done via The London Tenders Portal.', NULL, '25fa09db-1a23-43c3-94b7-8f3e39e4d113', (SELECT id FROM project_categories WHERE name = 'Web Development'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 60000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/b8e77ce7-9fcc-4df5-888d-2fef26930b14', NULL, NULL, NULL, ARRAY['Construction work', 'UK', 'Contracts Finder'], '2026-06-19', '2026-05-29', 'd1e4065a552ee7b3226fdf79318878c23189aee1a8c36b95dce43db7cc4d7167') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('34d3a977-4c2f-4640-952b-2c3c22a16c55', 'ocds-b5fd17-c9fa67ad-b56b-4cfe-ab1b-78e9f6508220', 'GB-Colchester: 0481-PA - Small Flat Roofs (Flats & Maisonettes - Contract G)', 'Colchester Borough Homes (the Authority) on behalf of Colchester City Council (the Council) wishes to commission a contractor to re-cover various single storey flat roofs, including porches, bay windows, and outbuilding roofs at various flats and maisonettes throughout the Colchester District.
      
      Further details of the requirements can be found in the accompanying documents. The form of contract to be used for this tender exercise is the JCT Intermediate Building Contract 2016 Edition (IC2016).

Additional information: The contract period is to be confirmed, but the works shall take no longer than 14 weeks. For the advert a start date of w/c 3rd August has been stated but bidders are to provide the actual timeline for the works as part of the submission.', NULL, '44a03d51-72ec-468c-9c1b-578d9a162331', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 500000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/2e8a1c9d-df94-45ac-9904-15eb58b705ec', NULL, NULL, NULL, ARRAY['Roof-covering work', 'UK', 'Contracts Finder'], '2026-06-26', '2026-05-29', '3cdd0760cf5b3b52ed6754acb738736414aa696631d8a0d43757c17a22e4f2c5') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('0510f89b-85a0-4a2c-8cfa-0c789857c921', 'ocds-b5fd17-d15321f5-0773-4f9b-8625-361de22e0ee4', 'Radford House - External Facade Works', 'Ramsgate Town Council will be appointing a contractor to undertake remedial works to the external façade of Radford House.

The works are located at the public facility in Ramsgate - previously the Old Fire Station, at 18-20 Effingham Street, Ramsgate, CT11 9AT. The exterior works are part of a wider redevelopment of the site, which will include internal alterations to the building, and temporary technicians accommodation (under separate contracts to follow)

The requirement of the repair and maintenance works is to ensure the deterioration of the building is prevented, the change of use proposals are implemented and heritage features of the original building are protected and restored.

The contractor is to undertake repair and maintenance works as listed within the attached documents. All works shall be undertaken in accordance with the client''s consultant''s approval.

The works need to be undertaken by an experienced contractor that have the necessary skills and experience to undertake the works as required.

The contractor will need to demonstrate their experience as part of their tender return.', NULL, '56f49980-8d11-4c50-9833-b399651e9343', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 175000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/33758a5e-b37b-47cf-999a-b16309b4adbd', NULL, NULL, NULL, ARRAY['Construction work', 'UK', 'Contracts Finder'], '2026-06-05', '2026-05-29', '606c0d97bd3bd7293c2b2a6d3fd4d39cf1245c7e2ddb0f1b227e2ed9c57ef175') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('2c23aa92-1880-44c1-a877-b35898abf668', 'ocds-b5fd17-f31b6a52-8225-4351-a1d3-f64ea7135e3d', 'Framework to upgrade existing buildings in Surrey for residents, particularly those who are vulnerable to high energy costs and poor health outcomes, and who currently live in substandard housing. These works from the Framework will look to improve energy efficiency, reduce carbon emissions', 'As part of Central Government''s Warm Homes Programme, SCC submitted an expression of interest to DESNZ in December 2024 for the successor fund to HUG 2 called the Warm Homes - Local Grant (WHLG) which was successful and allocated a record sum for SCC of £13.9 million of grant funding, to be utilised across the next three financial years.', NULL, '39d54a5e-225e-4b2c-b762-e709f29bda49', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 14000000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/6692e6e8-cb2f-4402-ab73-898895e87421', NULL, NULL, NULL, ARRAY['Refurbishment work', 'UK', 'Contracts Finder'], '2026-06-25', '2026-05-29', 'cdd1c03f16bb91e310ee229b8bed8d0a4a1c90a5113b868c9ad6e5a324aa361a') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('2a4b762a-53e4-446e-b13a-68ac59bdb77d', 'ocds-b5fd17-041221bf-0d86-41ad-b361-0fb5adacfb2a', 'M6 Lune Gorge - Steel, Concrete and Waterproofing Third Party Independent Inspections', 'Kier Transportation require a Subcontractor to undertake Third Party Independent Inspections for Steelwork fabrication, Precast Concrete fabrication and on site waterproofing over 7 bridges (14 structures) on the M6 Lune Gorge Junction 37 to 38.  

Please note that some of the inspection work may be required to be undertaken in Europe.

We will use the Build UK Common Assessment Criteria (CAS) to ensure a consistent minimum business competence. If your company possesses necessary qualifications and is interested in bidding for this project, please email infrastructure.procurement@kier.co.uk with your company''s portfolio, relevant experience, and references for further evaluation.', NULL, '1ab94104-c430-4214-918c-4ceaba391c74', (SELECT id FROM project_categories WHERE name = 'Enterprise Software'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 150000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/8094d007-00ca-4b07-b604-cb3a1a263dde', NULL, NULL, NULL, ARRAY['Building-inspection services', 'UK', 'Contracts Finder'], '2026-06-12', '2026-06-01', '637179541f700e1480a1d480ac253732c5b8be9ebe6f2bdfe3fe1056702ed259') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('283f1a1a-9912-491b-a1a5-2258f1034092', 'ocds-b5fd17-07ec2535-27cf-4ca2-86e0-3298e6c1b3af', 'The Delivery of a Digital Assessment to Action Programme for Winchester District Businesses', 'The council is seeking a local delivery partner to provide ten local (micro or small) businesses with a digital assessment that evaluates their current digital capability across key operational and commercial areas. This delivery partner must be local to the Winchester district due to the need to complete the majority of this programme in person. The assessment will be followed by a structured action plan, prioritising immediate improvements alongside longer-term strategic opportunities.

Digital assessment pathway:

1. Digital assessment: each business to be assessed in-person to establish baseline digital capability across key operational and commercial areas.

2.Tailored digital action plan: findings from the assessment are translated into a practical action plan, including prioritised recommendations, signposting to relevant support, introductions and funding opportunities where appropriate. (Provided within two weeks of the assessment date).

3. One-to-one digital support: businesses can receive up to four hours of tailored one-to-one digital support, focused on implementing priority actions (level of support dependent on complexity and need).

4.Progress check with each business: a check-in to review progress against the action plan, address barriers and refine next steps if required.

5.Final review and close with each business: a final review to summarise progress, capture outcomes and impact and formally close the support. If continued support is required, signposting to further support is essential.

6.Final report to the council of project summary: A full final programme report will be required at the end of the project. Including, business names, location, size of businesses, summary of assessments and their action plans and recommendations. Case studies of at least three businesses taking part that can be used for publicity and learning. All assessments and action plans to also be submitted to the council.

Bidders may seek clarification on any aspect of the request to quote. All clarification requests must be submitted by email to Emily Reason, Sector Project Officer, ereason@winchester.gov.uk by 9am Monday 1 June 2026. Any questions received by this deadline, together with the council''s responses will be circulated to all organisations who have shown interest in the project.

All quotes must be submitted by email to Emily Reason, Sector Project Officer, via the email address: ereason@winchester.gov.uk by no later than 9am Monday 8 June 2026. 

Please ensure you answer all of the requirements and questions throughout the specification document.', NULL, 'e37c470d-64a2-4659-83c9-5170cd95e653', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 10000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/5f8725b0-d8ae-49a5-93a1-978d948733b3', NULL, NULL, NULL, ARRAY['IT services: consulting, software development, Internet and support', 'UK', 'Contracts Finder'], '2026-06-08', '2026-06-01', '6e85c40f2741d2453931992efc119ecdc9b13858fe0371c75e5bbe6cd57bf1e6') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('f1c5f866-5414-411d-bf98-4b063baa4d2b', 'ocds-b5fd17-135f3fb6-aac4-428d-a854-0c33d9ef9103', 'Boiler Replacement and Associated Mechanical Works - The Monastery Manchester (Grade II Listed Building)', 'The Monastery of St Francis & Gorton Trust invites tenders from suitably qualified Mechanical and Electrical contractors for the replacement and upgrade of the existing heating and hot water infrastructure at The Monastery Manchester, a Grade II* listed building of national heritage significance.
The works comprise the removal and replacement of the existing boiler plant, flue system, hot water equipment, pumps, controls, and associated pipework. The project includes installation of new high-efficiency gas-fired boilers, a replacement vertical extract flue system, upgrades to the Building Management System (BMS), associated electrical and controls works, thermal insulation, commissioning, and preparation of as-fitted documentation.
The existing flue dilution system has reached the end of its operational life and will be replaced with a new vertical extract flue arrangement routed through the roof. The works will be undertaken within a live operational heritage environment and require careful integration with the historic fabric of the building.
Contractors must demonstrate relevant experience of delivering mechanical and electrical installations within historic, listed, or conservation-sensitive buildings and provide evidence of appropriate insurances and technical competence.
The anticipated construction period is six weeks commencing July 2026, subject to planning and listed building consent approval.

Tender documents can be obtained by downloading the attached procurement documents from this notice.
Interested contractors are encouraged to undertake a site visit prior to submission. Details of the site visit arrangements are contained within the tender documentation.
Completed tender submissions must be returned electronically no later than 13:00 noon on Tuesday June 2026', NULL, '66be0c00-a1da-43f6-9a42-46c36b64a2a6', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 180000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/0623626e-0de6-4629-b83c-7ec455aa03fc', NULL, NULL, NULL, ARRAY['Central-heating installation work', 'UK', 'Contracts Finder'], '2026-06-16', '2026-06-01', 'ed22b9b792c9f8616e45e007ba222da53aab666d2cbc093c18eb31568b5477b1') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('c8ccc9c9-c48f-414d-bfdd-c367d4fd62f5', 'ocds-b5fd17-1a4b915c-c38a-431e-86a5-d1876d357c71', 'Dynamic Purchasing System for Retrofit Programme Delivery Services', 'Procure Plus Ltd (PP) is a social housing regeneration consortium. PP specialises in the procurement of goods, works and services for the construction and maintenance of social housing properties.

Procure Plus is working with Local Energy Hub North West in establishing a dynamic purchasing system (DPS) for domestic retrofit programme delivery. The DPS is for contracting authorities and public sector organisations to contract retrofit advice, assessment and installation of measures for low-income households. A number of call-offs under the DPS will be financed via Green Home Grant LAD Phase 2 Funding.', NULL, 'a49791e3-60ad-449c-ae52-60d77ff18277', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 712500000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/3f58d7bc-0946-47c0-bd61-16cf69b5f1be', NULL, NULL, NULL, ARRAY['Building installation work', 'UK', 'Contracts Finder'], '2029-02-23', '2026-06-01', 'fecd2b18ea8fed2899f60b96131d2eae7f54b851c9051ec320750e1b5153b9d8') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('8f81e05b-c48d-4c7c-b070-351187e17cd4', 'ocds-b5fd17-2b66b3ed-7275-4e63-8031-8e0c7e0f1ccf', 'Leach Pottery Museum Interpretation Fitout Contractor', 'Interpretation Fit-Out Build Contractor - The Leach Pottery, St Ives, Cornwall

The Bernard Leach (St Ives) Trust Ltd invites tenders from suitably experienced contractors to deliver interpretation/exhibition fit-out works across the Leach Pottery site in St Ives, Cornwall. This commission forms part of a major £10 million capital redevelopment of one of the world''s most significant studio pottery heritage sites, funded with support from the National Lottery Heritage Fund.

Contract Value: £375,000 - £400,000 (exclusive of VAT)
Contract Form: JCT Intermediate Building Contract with Contractor''s Design (ICD) 2024

Practical Completion: 4 June 2027
Site Opening: 18 June 2027

Scope of Works:
The appointed contractor will act as Principal Designer and Principal Contractor, responsible for the manufacture, supply, and installation of four main packages: setworks and 3D elements; display showcases (including Government Indemnity Scheme standard cases); graphics and 2D elements production; and exhibition lighting supply. 

Works span multiple spaces, including the historic Grade II listed Pottery buildings; refurbished 2008 extensions; new build Learning studios and reception areas; outdoor spaces, and cross-site wayfinding. 

Full coordination with the client (The Bernard Leach (St Ives) Trust Ltd), base build contractors (Dow Jones Architects), interpretive designers (Extended Studio), and the separately appointed AV contractor will be required. Audiovisual hardware and software are contracted separately and are out of scope.

Key Dates as per ITT document:
* Site visits (compulsory): Tuesday, 28 April - Thursday, 28 May 2026
* Clarification deadline: Noon, Friday, 29 May 2026
* Clarifications published: Monday 1 June 2026
* Submission deadline: Noon, Friday, 12 June 2026
* Evaluation: w/c Monday 15 June 2026
* Interviews (shortlisted): Friday, 26 June and Monday, 29 June 2026
* Contract award (notification): Tuesday, 30 June 2026
* Online kick-off meeting Monday, 13 July 2026
* Contract commencement: Monday, 27 July 2026
* On-site installation: Monday, 22 March - Monday, 31 May 2027
* Practical Completion: Friday, 4 June 2027

Submission Requirements:
Bidders must submit: 
* Completed Form of Tender; 
* Completed Submission Questionnaire; 
* Fully completed Pricing Schedule; 
* Proposed programme of works
* A tender proposal addressing five quality questions as specified in the ITT
* Required policies, evidence of insurance and certification as specified in the ITT

All bidders must complete a compulsory site visit before submitting. Submit to Sara Matson at projectlead@leachpottery.com by noon on Friday, 12 June 2026.

Evaluation: Quality 65% / Price 35%

Additional information: The Leach Pottery Interpretation Fit-out and cross-site wayfinding is the culmination of a 2-phase capital programme generously supported by:

St Ives Town Deal (Central Government / Cornwall Council)
National Lottery Heritage Fund
Arts Council England
Wolfson Foundation
Clore Duffield Foundation
The Headley Trust', NULL, '9b96d9df-2dc3-4923-900b-4ba3cdcfcb1f', (SELECT id FROM project_categories WHERE name = 'Enterprise Software'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 400000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/920bb370-1618-4726-847a-2bdc2e2e56c4', NULL, NULL, NULL, ARRAY['Museum services and preservation services of historical sites and buildings', 'UK', 'Contracts Finder'], '2026-06-12', '2026-06-01', '035b253002c8466132a8cee9a4af38aac0fa32574a39a93daca13aba990ac2ef') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('fe3f055b-e10e-4e3a-9620-aa18ad5334bb', 'ocds-b5fd17-332395f1-7024-4298-9413-a29409993bf2', 'A66 Northern Trans-Pennine Project (NTP) - Schemes 1 & 2 Tree and Vegetation Clearance Phase 2', 'Kier Transportation intends to engage experienced and qualified contractors to undertake works associated with the tree clearance of all remaining arboricultural operations required to facilitate the Scheme 1&2 construction works, following the prior completion of Phase 1 tree clearance activities. 

The A66 project is to be delivered in collaboration by three Tier 1 contractors, Balfour Beatty, Kier and Keltbray.

We will use the Build UK Common Assessment Criteria (CAS) to ensure a consistent minimum business competence. If your company possesses necessary qualifications and is interested in bidding for this project, please email infrastructure.procurement@kier.co.uk  with your company''s portfolio, relevant experience, and references for further evaluation.', NULL, '1ab94104-c430-4214-918c-4ceaba391c74', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 200000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/dd243e30-cb96-49c3-92ad-580cca265e9f', NULL, NULL, NULL, ARRAY['Demolition, site preparation and clearance work', 'UK', 'Contracts Finder'], '2026-06-19', '2026-06-01', 'df09e9fee2cb4d0ad66d13237160dafae55037c519a78e57f5b59ff88e142b50') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('bf1edadf-516a-4520-9a67-d3d996cfb41d', 'ocds-b5fd17-3ececb37-0c1f-4f9b-836b-02e461ede649', 'Supply of Baked & Frozen Products (Pasties, Savouries etc.)', 'Falmouth Exeter Plus (FXPlus) is looking to appoint a supplier on an Initial Term 36-months contract with Extension Options to extend by up to 24 months (2 x 12-months)  giving a Total potential duration of  60-months to supply and provide services for our Baked & Frozen Produce (Pasties, savouries etc.) for the University Campuses at Falmouth (Woodlane, Falmouth) and Penryn (Treliever Road, Penryn).', NULL, '1248fd5d-422d-43aa-a26a-f1ec85b2fab8', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 450000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/49502d76-4bb7-4a74-8399-81d4604c9318', NULL, NULL, NULL, ARRAY['Food, beverages, tobacco and related products', 'UK', 'Contracts Finder'], '2026-07-17', '2026-06-01', 'caf5f8f2239141629dcede430e6f9b6c623d0741a356edbfda3978c920639236') ON CONFLICT DO NOTHING;
