INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('70063a6d-c51d-46a7-8ecb-2d3f0e18f4a5', 'ocds-b5fd17-3202f230-5093-461b-92ae-37e54e4a19a8', 'High Speed OCS Design, Construction, Testing & Commissioning Approved Body Engagement', 'Colas Rail are looking to engage with an Approved Body to support with obtaining UK declaration of conformity for its Interoperability Constituents (ICs) relating to specific elements of first principle Overhead Catenary System (OCS) design elements and to provide re-certification of the existing TSI compliant system design to NTSN in support of its OCS Design, Construction, Testing & Commissioning activities on behalf of HS2.

Additional information: The services shall be delivered in accordance with Colas Rail CR2 Professional Services Agreement Terms & Conditions, including applicable HS2-specific provisions; copies will be issued to shortlisted suppliers.
        
        Suppliers to submit their tender proposal by the tender deadline of Wednesday 17 June 2026 by email to tr.procurement@colasrail.com.
        
        If you have any questions, please send them to tr.procurement@colasrail.com and we shall endeavour to respond to them at the earliest.', NULL, '6637f847-557b-4014-9271-e1c72315b702', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 250000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/5e2d38d2-8b2f-4d4b-bc46-3d872b0b82e5', NULL, NULL, NULL, ARRAY['Monitoring and control services', 'UK', 'Contracts Finder'], '2026-06-17', '2026-06-04', '86f296a9de6a4b9ebe490271d87e7ff16912947eb8283760ff40fbb9ddd26860') ON CONFLICT DO NOTHING;
