INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('2f38e1e1-8410-4b42-9a2c-653e3096c3c4', 'ocds-b5fd17-1af1ba70-1cd2-49c5-93ca-e064a416280a', 'Rotary Frequency Converter', 'We require a rotating machine manufacturer to design, build and install a 5MVA 11kV 50Hz to 6.6kV 60Hz Rotary Frequency Convertor. Both machines shall be synchronous with a mechanical coupling joining the 10-pole motor to the 12-pole generator. There is a requirement to be able to physically rotate the generator stator to enable manipulation of the phase and load angle via racking motor or actuator. The machine should come complete with a starting reactor and contactor connected to the neutral point of the motor, to limit the inrush current on startup to approximately 400A.  Control of the machine starting reactor and racking equipment shall be by an external control system, which shall not form part of the machine scope of supply.', NULL, 'f10b6745-0a24-4385-907a-93fcd96f2f15', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 2000000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/cb4187fa-1f56-4e0a-802b-38148d143d40', NULL, NULL, NULL, ARRAY['Electric rotary converters', 'UK', 'Contracts Finder'], '2026-07-10', '2026-06-08', '8094948b7d8bb4fae2dfee0e9e5b7e01712aeeb504a555447c5820db419dc2ea') ON CONFLICT DO NOTHING;
