INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('b8149136-14ee-48f5-878d-f08ae293dd5a', 'ocds-b5fd17-f513251d-d417-44b7-8adf-ee3296c4a851', 'Single Tender Award for purchase of Pol-Ed', 'Humberside OPCC is purchasing Pol-Ed an educational web platform on behalf of all schools and other youth organisations in Humberside.

Pol-Ed has been developed by West Yorkshire Police and is designed to provide a comprehensive suite of educational resources tailored to all key stages, enabling schools to access high-quality materials. These include structured lesson plans deliverable by school staff, youth leaders and others working with CYP, police officers and PCSOs, as well as bespoke content suitable for targeted interventions with children engaged in the Youth Justice System. The platform will be made available to all educational establishments across Humberside, as well as to key partners, including our four local authorities and Humberside Police.

This procurement is being done via a Single Tender Action, as no other similar product exists within the market.', NULL, 'ec0b5c0d-4500-47b7-80a0-6a0025da04b6', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 30000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/1f2ff414-ec43-468a-8840-e0cba7958017', NULL, NULL, NULL, ARRAY['Education and training services', 'UK', 'Contracts Finder'], '2025-10-12', '2026-06-11', '23a39c5ae0ad822cfa5d4f9054c3f909d19f29eb64bde9cecabf21e85d1d6728') ON CONFLICT DO NOTHING;
