INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('19790595-fe3c-44cc-a1a0-347f4ad4570b', 'ocds-b5fd17-ca9090b8-05d7-4635-84ed-0ff398043134', 'MRWA Food Waste Prevention campaign 26/27', 'MWDA is seeking a creative agency to deliver a strategic behavioural change campaign under the Zero Waste LCR brand. The campaign is to help raise awareness of household food waste and food waste prevention behaviours across the Liverpool City Region.', NULL, '0d35620c-1c0a-41de-a389-1cc38b1ddba1', (SELECT id FROM project_categories WHERE name = 'Enterprise Software'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, NULL, NULL, 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/29cf4a56-bdbe-4c37-9f42-8c3db98ea06c', NULL, NULL, NULL, ARRAY['Advertising and marketing services', 'UK', 'Contracts Finder'], '2026-07-13', '2026-06-17', '1480ad0773469ec7fa688f8c90cd6cafad6bb1596fc87d5950fe21f633f6d935') ON CONFLICT DO NOTHING;
