INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('c82195b2-a9c9-42e7-99ac-14a7e1fd09df', 'ocds-b5fd17-d349e746-dec8-41a5-9ce4-fd248b08e12f', 'Two Play Park Upgrade Projects', 'Redevelopment of two play spaces in Melksham: Dunch Lane Play Park, designed for children aged 0-4 years, and Riverside Play Park, designed for children aged 5 and over. Together, the project aims to deliver high-quality, inclusive and imaginative play environments that respond to community priorities, reflect their surroundings and provide lasting value for children, families and the wider community. Both parks should be designed in line with the PiPA Play framework and advice, ensuring accessibility, inclusion and play value are considered throughout the design, delivery and ongoing management of each space.

To register your interest; https://forms.office.com/pages/responsepage.aspx?id=36tjsR7s90ucHmmJlKHwttxJsJG6kw9OrPTOZ2CxBhpUNTZQT1U0VVI0UzBZVVhUVktEM0NFQUY0Uy4u&route=shorturl', NULL, 'a7bf5539-ef86-4376-b23a-80f20d04fdc0', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, NULL, NULL, 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/8284d2cd-3b24-48aa-a2b1-f4e8d8083901', NULL, NULL, NULL, ARRAY['Playground equipment', 'UK', 'Contracts Finder'], '2026-08-06', '2026-06-25', '97ecfbcf66a20b60dd9afcb5cd41eef40f0ec7a14e504dfcf69d625ea1e597ec') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('e86e59fd-6aa3-4abe-a4bc-0eda0a146b0e', 'ocds-b5fd17-e5a23bb2-7a96-44d6-9457-f8c7072f7f3d', 'M6 Lune Gorge - Roundthwaite Box - Civils Package', 'Kier Infrastructure are looking to engage experienced and qualified contractors for the civils package for Roundthwaite Box solution in the Central Reservation works on the M6 Lune Gorge Scheme (Approx J38). Package is inclusive of but not limited to: Back of wall drainage,  excavations, pile cutting or burning, site preparation and rectification, demolition, minor temporary works, backfilling. Interest can be flagged in accordance with other linked Roundthwaite Box advertisements.

We will use the Build UK Common Assessment Criteria (CAS) to ensure a consistent minimum business competence. If your company possesses necessary qualifications and is interested in bidding for this project, please email infrastructure.procurement@kier.co.uk with your company''s portfolio, relevant experience, and references for further evaluation.', NULL, '1ab94104-c430-4214-918c-4ceaba391c74', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 50000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/186db4a8-e53f-414f-9f55-a1e5b159a926', NULL, NULL, NULL, ARRAY['Site preparation work', 'UK', 'Contracts Finder'], '2026-06-30', '2026-06-25', '644cbb0361ceeb9ca97407c975c44143eaf43d12c130b5ea6915aa132c23629c') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('665770f2-8327-4621-8095-b0a91e0dd875', 'ocds-b5fd17-eda153f3-eb11-4a4d-8d10-762cc308af17', 'South Cambridgeshire District Council - Shared Ownership Sales and Marketing Arrangements', 'SCDC has a continuing new build programme that includes shared ownership and affordable rent and social rent homes. SCDC need to build out policy-compliant exception sites and purchase S106 affordable housing from developers. SCDC''s policy generally requires 70% rented and 30% shared ownership as the affordable housing mix. On occasion if required by viability to balance a scheme budget SCDC may also build market sale homes.

SCDC Housing Team is therefore looking for a suitably qualified and experienced service provider to provide expertise in the marketing and onward sale of shared ownership or market sale units. The service provider will need to have an established history/track record of this field and shall use a cohesive team targeted at this bespoke area.  SCDC have a growing shared ownership homes programme which currently had in excess of 30 sales in 2025-26 and 44 are expected in 2026/27. 

Should you be interested in this opportunity, the full tender documents can be found on our e-tendering portal via the following link: https://procontract.due-north.com/Advert?advertId=58926d7d-a270-f111-813c-005056b64545
', NULL, 'c5f00bba-f2bc-4217-8da0-5c6afa4ee5e2', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, NULL, NULL, 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/3baa95d2-10f5-4d9d-b612-be8e336fe70b', NULL, NULL, NULL, ARRAY['Property management services of real estate on a fee or contract basis', 'UK', 'Contracts Finder'], '2026-07-09', '2026-06-25', '3c223dce333de4ee9ca98c8881d7a9da02e3a473b03fe0d2954e645314b98ee2') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('74e0fb28-3d2a-4e2f-844c-0b65c0eb9bff', 'ocds-b5fd17-fb6dd247-352e-4b3f-8139-9b0d2628f8a6', 'Ellesmere Town Council Sanitary Disposal and Servicing', 'To Provide Sanitary Disposal as follows:-
Installation and monthly service / exchange of:

Site 1 - Ellesmere Town Hall
4 Slimline Feminine Sanitary Units.
1 Nappy Unit
1 Dual Vending Machine
2 Water Management Systems

Site 2 - Cross St, Public Conveniences
1 Washroom Air Steriliser
4 Slimline Feminine Sanitary Units
2 Nappy Units
1 Dual Vending Machine
1 Water Management System

To provide servicing as follows: -

Annual service of ''Flowsaver'' Water Management Systems.
Six weekly service of Dual Vend machine.

Documentation:-

Contractors will be expected to produce appropriate Waste Transfer Notes and service reports.

Health & Safety:-

Contractors will be expected to provide fully trained operatives and provide the Council with copies of its risk assessments associated with this work.

Insurance:-

Employers and Public Liability must be held and produced to the council by the Contractor on commencement of any contract.


Contract Payments:-

The contract value will be paid monthly upon receipt of invoice(s) unless otherwise negotiated.

Please forward any enquiries and quotes to : Jean Hynes at assistant.clerk@ellesmere-tc.gov.uk', NULL, '8fa64e35-7929-4c66-b43b-114b4ea27d01', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 3300, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/dea74f0d-78bf-4bfe-8615-0319951c9d44', NULL, NULL, NULL, ARRAY['Provision of services to the community', 'UK', 'Contracts Finder'], '2026-07-03', '2026-06-25', 'e235d98e2a09df063baeab303d5ed1e91a2b6589394f53f3e1aacfedb11834a8') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('df8f6dfd-dfc9-413e-ac3c-4ccc34cc5db5', 'ocds-b5fd17-05f029d6-35cc-4af7-bf52-bd758d0202d5', 'Handling of Recyclable Materials', 'Modification Notice
      Original description: Handing of Recyclable Materials for the Council.
      Description of the modifications
      This contract relates to the Council''s waste disposal arrangements for non-residual waste. The proposed 12-month extension, from 1 August 2027 to 31 July 2028, will ensure continuity of service during the period of Local Government Reorganisation (LGR). For a range of organisational and strategic reasons, a 12 month extension to this contract is now needed so that, after LGR, North East Essex Council can take decisions in relation to any re-procurement of services to meet its requirements.
      Description of the economic or technical reasons and the inconvenience or duplication of cost preventing a change of contractor:
      The Council relies on Regulation 72(1)(c) of the Public Contracts Regulations 2015 in relation to this extension. The need for modification has been brought about by circumstances which a diligent contracting authority could not foresee The Council did not, in 2022/23 when this contract was being procured, foresee that Local Government Reorganisation (LGR) would take place in 2027/28. This extension means that after LGR, North East Essex Council can take decisions relating to a re-procurement
      Description of the circumstances which rendered the modification necessary and explanation of the unforeseen nature of these circumstances:
      This contract relates to the Council''s waste disposal arrangements for non-residual waste. The proposed 12-month extension, from 1 August 2027 to 31 July 2028, will ensure continuity of service during the period of Local Government Reorganisation (LGR). For a range of organisational and strategic reasons, a 12 month extension to this contract is now needed so that, after LGR, North East Essex Council can take decisions in relation to any re-procurement of services to meet its requirements.', NULL, 'c298cefe-d98e-43a7-b9a2-0c900da44efb', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 1, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/bfc41558-bf34-47fe-9a81-680224d64057', NULL, NULL, NULL, ARRAY['Refuse recycling services', 'UK', 'Contracts Finder'], '2026-06-01', '2026-06-26', '106e028ce5a22d64f41156b18687e963f6a6b1cb9561f29dcfcb746a0bc8284a') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('864d1b52-a4d2-4ea4-9c9c-f5fe58291dc3', 'ocds-b5fd17-10c9914f-f45c-4df2-89e0-a440714888bd', 'BMS (Building Management System) Phase 1', 'Ravensbourne University London is pleased to invite your organisation to submit a tender for the initial advance works package associated with the Ravensbourne University London - BMS Upgrade Project. The project comprises a phased upgrade of the University''s existing Trend Building Management System estate, including the replacement of legacy Trend IQ Series controllers and the migration from the existing Trend 963 supervisor to the IQ Vision platform. As an initial phase of the project, Ravensbourne University is seeking competitive tenders for the replacement of the Level 2 Fan Coil Unit Controllers only. The University intends to undertake these works during August 2026 and is seeking confirmation of your ability to resource and deliver the works within the available programme period. Tenderers are requested to submit a fixed price for the Level 2 Fan Coil Unit Controller replacement works only, as detailed within the tender documentation provided.', NULL, '86956d01-197e-4ef9-879d-706ea98a104b', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, NULL, NULL, 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/36bcb77e-4f3a-4e55-899e-3edc8def8be6', NULL, NULL, NULL, ARRAY['Installation services of guidance and control systems', 'UK', 'Contracts Finder'], '2026-07-17', '2026-06-26', 'edf9677223585cad70d5f38e26c7034af07cee0a36c1866811fb2d700947b518') ON CONFLICT DO NOTHING;
