INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('4e2181d6-0837-48e9-b83e-466932b12a56', 'ocds-b5fd17-20bb54ca-294a-45bf-9449-0beea881e456', 'The Council i procuring an Appropriate Adult Service in accordance with it tatutory dutie under the Police and Criminal Evidence Act 1984 (PACE) and the Crime and Di order Act 1998 ( ection 38(4)(a)). The e tatutory dutie place an obligation on local authoritie to en ure the provi ion of Appropriate Adult for children and vulnerable adult where a parent, guardian or other ui', 'The Council is procuring an Appropriate Adult Service as is required under Police and Criminal Evidence Act 1984 (PACE) and Crime and Disorder Act 1998, section 38(4)(a) which place a statutory duty on local authorities to provide Appropriate Adults for young people and vulnerable adults when a parent/guardian or other suitable adult is not available or appropriate.', NULL, '39d54a5e-225e-4b2c-b762-e709f29bda49', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 1050000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/8ef1b773-1b75-4280-ae9e-b35c111ae7a8', NULL, NULL, NULL, ARRAY['Health and social work services', 'UK', 'Contracts Finder'], '2026-07-27', '2026-06-26', '6118cd9d6a0dc2cb811bd2307750dff1af79c3abd91b3dd3ab3028fef2587d3d') ON CONFLICT DO NOTHING;
