INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('7d73a549-25be-41e0-8218-2b34ecddbf3c', 'ocds-b5fd17-94a43631-08c4-494f-845c-0e0bcfb0c65e', 'Supply and/or Install of Rooftop Solar Photovoltaic Systems and Associated Equipment Y24013', 'Modification Notice
      Original description: The Framework Agreement is divided into five separate Lots: Lot 1 - Supply of Solar Panels and associated equipment Lot 2 - Installation of Solar PV Systems and associated equipment Lot 3 - Supply and Installation of Solar PV Systems and associated equipment Lot 4 - Supply and Installation of Specialist Systems. Lot 5 - Power Purchase Agreements (PPA) and other innovative funding
      Description of the modifications
      Modification required due to supplier withdrawal and to confirm values
      Description of the circumstances which rendered the modification necessary and explanation of the unforeseen nature of these circumstances:
