INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('d344e961-0377-4ab7-885a-722e20a98e3f', 'ocds-b5fd17-70b4946f-879f-4cc8-b8ca-342875acc7bf', 'Die Bonding System', 'Funding is available to purchase a die attach/bonding system capable of performing a wide range of bonding processes, including ultrasonic, flip-chip, and UV curing, which is suitable for prototyping and light production runs. As a result, a crucial aspect for any die attach system under is the ability to be used for bonding runs as small as a single die should this be required. This stipulation lends itself to a semi-automated (i.e. motorised) system, ideally with the capacity to store process recipes to maximise reproducibility should the system be used for light production runs.', NULL, 'f570ee2b-9ccb-4d1a-93bf-a9cb3edaf851', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 215000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/21933349-7465-49c1-a0c0-59f1caeb33ed', NULL, NULL, NULL, ARRAY['Laboratory, optical and precision equipments (excl. glasses)', 'UK', 'Contracts Finder'], '2026-07-16', '2026-07-01', '40af5ef78e69111e282e157aaf1144ca33637e576dca7e86c6e276d929e38230') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('1ecdb362-cbc4-452c-96f8-ec66587cc4e1', 'ocds-b5fd17-a4bc90a7-edc6-47d1-ba37-f1961d92bc8a', 'GB-Leeds: PE2025_26-5345 Provision of Christmas Trees, Lights and Associated Works', 'The University of Leeds requires a supplier to provide Christmas trees, lights and associated works across the University estate. The requirement includes the supply, delivery, installation, testing, maintenance, call-out support, removal and any associated works necessary to provide safe, high-quality and visually appropriate Christmas displays. Tenderers must be able to deliver within the required seasonal programme, coordinate effectively with University stakeholders, manage health and safety risks, minimise disruption to students, staff, visitors and University operations, and meet all requirements set out in the full tender pack.

Additional information: The contracting authority considers that this contract may be suitable for economic operators that are small or medium enterprises (SMEs). However, any selection of tenderers will be based solely on the criteria set out for the procurement.', NULL, '2d6ebd43-9c1f-4e37-91b8-1eea81e1c8aa', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 25000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/a21cd552-02f5-46de-9594-f1e169aa7f3d', NULL, NULL, NULL, ARRAY['Christmas tree lights', 'UK', 'Contracts Finder'], '2026-07-29', '2026-07-01', '552aa467253e47a7ee7ce835577625c9a141541d81441bc447205c67189455e2') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('a8f8d2bd-6ba5-44b8-8f73-ad44e29e9bdf', 'ocds-b5fd17-a7e11bb1-034c-4075-b5d9-d3cb427e6b42', 'A66 Northern Trans-Pennine Project (NTP) - Schemes 1, 2 and 6 Drainage Materials Provider', 'Kier Infrastructure are looking to engage experienced and qualified Supplier for the provision of Drainage Materials for the main works on the A66 Northern Trans-Pennine scheme. The A66 upgrade will see single-lane sections of the 80km stretch between the M6 and the A1 made into dual carriageway, while key junctions will be improved.

The A66 project is to be delivered in collaboration by three Tier 1 contractors, Balfour Beatty, Kier and Keltbray.

We will use the Build UK Common Assessment Criteria (CAS) to ensure a consistent minimum business competence. If your company possesses necessary qualifications and is interested in bidding for this project, please email infrastructure.procurement@kier.co.uk  with your company''s portfolio, relevant experience, and references for further evaluation.', NULL, '1ab94104-c430-4214-918c-4ceaba391c74', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 80000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/a632d3f3-1d65-4f78-89f1-6e0842704fd5', NULL, NULL, NULL, ARRAY['Drainage pipes', 'UK', 'Contracts Finder'], '2026-07-08', '2026-07-01', '1151052d2ccba29cd5a65cd433a55c006382b28720900f02808db3586df2bc85') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('cb49bb6f-2b99-4578-80ad-bb792bb56aa2', 'ocds-b5fd17-b8cbdb37-cd37-4f87-ba2b-9a877091b628', 'HS2 OCS - Technical Specification & Certification of the UK Wiring Consist', 'Colas Rail UK intends to procure and operate a Wiring Consist for the installation of contact and catenary wire.

The Consist comprises of two powered modules

Wiring Module a self propelled rail vehicle equipped with a four cable wiring module and two capstans.
Stringing platform a self propelled vehicle equipped with an elevating/rotating platform and one wire positioning unit.

Colas Rail requires specialist technical support from a suitably competent organisation to

Assess and recommend the most appropriate operational and certification strategy for the Wiring Consist.
Identify the applicable UK legislative, standards, compliance and acceptance requirements.
Support the development of a technical specification suitable for procurement and tendering to manufacturers.
Support the definition of the certification and acceptance process for the selected solution.
Provide technical support during manufacturer engagement and subsequent certification activities, as required.

Additional information: The services shall be delivered in accordance with Colas Rail CR2 Professional Services Agreement Terms & Conditions, including applicable HS2-specific provisions; copies will be issued to shortlisted suppliers.
        
        Suppliers to submit their tender proposal by the tender deadline of Thursday 23 July 2026 by email to tr.procurement@colasrail.com.
        
        If you have any questions, please send them to tr.procurement@colasrail.com and we shall endeavour to respond to them at the earliest.', NULL, 'c298cefe-d98e-43a7-b9a2-0c900da44efb', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 15000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/a3b4c913-5e5a-4e34-a175-a07d48799ddf', NULL, NULL, NULL, ARRAY['Architectural, construction, engineering and inspection services', 'UK', 'Contracts Finder'], '2026-07-14', '2026-07-01', '81fe1d5298b3e9f4cb25506fabc667ee3b3d1231cb4074f48c629562dfa2b73b') ON CONFLICT DO NOTHING;
