INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('82d99319-cbff-404e-a9c7-76644fcbc0d8', 'ocds-b5fd17-cd6a970f-d447-401d-ae56-dceed4f08411', 'Photonic Component Testing System', 'Funding is available to purchase a laser-based photonic component testing system which is capable of rapidly modifying the wavelength (>100 nm/s sweep rate) with a high level of precision (sub-picometer wavelength resolution). Such a system must also be able to accurately measure the wavelength-dependent power to allow for characterisation of a device under test (DUT). Such a system would strongly complement the photonics capabilities available to the QTIC/BIZ community.', NULL, 'f570ee2b-9ccb-4d1a-93bf-a9cb3edaf851', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 85000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/5b465ae6-1c39-4a0a-84c0-dc7fdf01db16', NULL, NULL, NULL, ARRAY['Laboratory, optical and precision equipments (excl. glasses)', 'UK', 'Contracts Finder'], '2026-07-16', '2026-07-01', '0624c9437427c4d331809b79165edf15802f4532aecf4e83983156398c57bc84') ON CONFLICT DO NOTHING;
