INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('88aca35a-8994-4128-8afa-ae37506561c9', 'ocds-b5fd17-ed64dbad-555a-4ed7-b25a-3515347c1211', 'Food Waste Consultancy - ESPO 664_25 Lot 8b Further Competition', 'Worcester City Council has appointed a Consultant to design, mobilise, and support the implementation of a new household food waste collection service. The Consultant will work collaboratively with the Council, its waste contractor(s), and key partners to ensure the service is deliverable, cost effective, compliant with relevant legislation, and capable of achieving high participation and capture rates.

This commission covers the period up to, but not including, the live implementation of the service. The Consultant will provide specialist technical, operational, and project management expertise to prepare the Council for a successful transition to delivery.', NULL, '392cc92b-7f4b-4e78-b614-3d5ffd7c68e9', (SELECT id FROM project_categories WHERE name = 'GIS'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 51065, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/dd56ace5-9707-4993-b0e6-96d1c1fa53c9', NULL, NULL, NULL, ARRAY['Consulting services for water-supply and waste consultancy', 'UK', 'Contracts Finder'], '2026-03-13', '2026-07-01', 'd1407464ece6bb5b43eb76781564cc8dafff787ba0333b9dd61f8a218bbdf371') ON CONFLICT DO NOTHING;
