INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('5a2acdd9-b107-4d15-8579-fb64b7c21b57', 'ocds-b5fd17-125f0aa5-aed0-4ddd-98c2-3eef65cddc01', 'Virtual School - Clinical Psychology Led Education Support', 'Liverpool City Council, through Liverpool Virtual School, is seeking a provider to deliver a psychology-informed workforce development and consultation service that supports children in care, previously looked-after children, and children with a social worker. The service will provide trauma-informed and attachment-aware consultation, training, reflective supervision, and strategic leadership support to schools, social care professionals, carers, and Virtual School staff. The focus is on improving educational planning, inclusive practice, workforce capability, and multi-agency collaboration through psychologically informed approaches that strengthen understanding of children''s needs, behaviour, wellbeing and engagement in learning. The service is educational rather than clinical, and no therapy, diagnosis or treatment is required under the contract.

The contract is valued at £75,600 per annum, with an initial term of 3 years and an option to extend for a further 12 months, giving a potential total contract value of up to £302,400 (inclusive of the extension period). Delivery will comprise approximately 88 days per year over an 11-month period.', NULL, '972411c6-3707-4765-ab8d-ebe0f22209f8', (SELECT id FROM project_categories WHERE name = 'Enterprise Software'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 302400, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/5040ca04-e88a-4b71-8a2f-139996449fe1', NULL, NULL, NULL, ARRAY['Social work services', 'UK', 'Contracts Finder'], '2026-07-31', '2026-07-02', 'a5350884e22399e0bc23daba3718dd96f1937d3006c2f68c4bb3c22798092aa2') ON CONFLICT DO NOTHING;
