INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('98dd635f-64d7-4967-baa9-3380b53b38a7', 'ocds-b5fd17-df038a1f-97e5-455c-8204-167b32425f4b', 'Distribution of Teacher Learning Materials in Malawi', 'The purpose of this Invitation to Tender (ITT) is to invite suitably qualified and experienced logistics service providers (the "Supplier" or "Tenderer") to submit proposals for handling and distribution of Learner workbooks and Teacher Guides to all public primary schools across all districts in Malawi for Term 1 and Term 2 of the 2026/2027 academic year.', NULL, 'b137afb4-2aff-4019-bdbe-9ab8f5782ba3', (SELECT id FROM project_categories WHERE name = 'GIS'), 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 80000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/3dce76ad-e371-47fa-bc82-6813d0255f15', NULL, NULL, NULL, ARRAY['Road transport services', 'UK', 'Contracts Finder'], '2026-07-17', '2026-07-03', 'cab161cb6a941f49ec361533840d794ef913dd6431079f927615643d92ca374b') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('b83eceaa-1691-4812-8816-d500845bcec3', 'ocds-b5fd17-ecd952a2-623f-418b-9ccf-c1210aef0c72', '​​Carbon Market Opportunity Assessment​', 'The UK Government''s Partnering for Accelerated Climate Transitions (UK PACT) programme is inviting quotations from qualified suppliers or consortia to deliver an economy-wide assessment of carbon market opportunities and institutional capacity strengthening support in the Philippines.

The Philippines has committed to an ambitious Nationally Determined Contribution (NDC), targeting a 75% reduction and avoidance of greenhouse gas emissions by 2030. Achieving this target will require significant international support, strengthened institutional capacity, and the mobilisation of climate finance to accelerate mitigation action across priority sectors.

Carbon markets are increasingly recognised as a potential mechanism to unlock climate finance and support cost-effective emissions reductions. As the Philippines advances implementation of its updated NDC, Nationally Determined Contribution Implementation Plan (NDCIP), and Long-Term Strategy (LTS), there is a timely opportunity to assess how carbon markets, including potential participation under Article 6 of the Paris Agreement, can contribute to national climate objectives while maintaining environmental integrity and alignment with national priorities.

The Climate Change Commission (CCC) is seeking a qualified supplier to support the next phase of this UK PACT partnership. Building on previous support provided through UK PACT, including the development of the Philippine Emissions Pathway Calculator (PEPC), this assignment will strengthen the evidence base and institutional capacity required to guide the development of carbon markets in the Philippines.

The selected supplier will undertake an economy-wide assessment of carbon market opportunities, including indicative mitigation and revenue potential across priority sectors, sector prioritisation, and the development of a preliminary pipeline of carbon market opportunities. In parallel, the supplier will provide targeted technical assistance and capacity-building support to strengthen the CCC''s ability to oversee, coordinate, and guide carbon market development in collaboration with relevant government agencies and stakeholders.

Interested suppliers are invited to review the documentation provided in this notice and submit their applications to: philippines@ukpact.co.uk', NULL, 'c6f70188-ab70-4e8d-a8a6-f504f6ead130', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 125000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/f2258fd3-f905-4718-aa61-b9332e22a733', NULL, NULL, NULL, ARRAY['Agricultural, farming, fishing, forestry and related products', 'UK', 'Contracts Finder'], '2026-07-27', '2026-07-03', 'e475ebe82c8499fe63bccbdf5e3cbb8bc2bb00560f64ed008e39debc917710fc') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('27a5a4cc-11e3-480e-9573-969858034156', 'ocds-b5fd17-f72f21df-a950-446a-ac7e-0a7516afdaed', 'Opportunity to Tender - Track / Access Matting - Regional Framework Lots (England) - J. Murphy & Sons', 'J. Murphy & Sons invites expressions of interest from experienced track matting suppliers subcontractor for inclusion on a framework of regional lots across England, supporting major infrastructure programmes.

The framework will provide opportunities to supply and install temporary access solutions on a call off basis, aligned to project locations and regional delivery teams.

Project Portfolio Includes
Network Rail CP7
TransPennine Route Upgrade TRU
Peel Ports
Other rail and infrastructure projects across England

Scope of Services
Supply and installation of temporary access trackway
Working platforms, access roads, crane pads and compounds
Maintenance and removal of track matting
Reactive and project based requirements

Suitable For
Track matting specialists with construction or infrastructure experience
SMEs and regional suppliers encouraged
Demonstrable H&S, environmental and quality performance
Ability to mobilise to live and constrained sites

How to Apply
Suppliers must express interest through CompeteFor to receive further tender information, including lot structure and next steps.

About the buyer''s selection process
Regional Approach
The framework will be structured into regional lots within England, enabling suppliers to tender for one or more regions based on capability, capacity and coverage.', NULL, 'c298cefe-d98e-43a7-b9a2-0c900da44efb', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 1000000, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/de62f81c-cb37-433a-bc18-0a10b3414ac4', NULL, NULL, NULL, ARRAY['Civil engineering support services', 'UK', 'Contracts Finder'], '2026-07-10', '2026-07-03', '5e6c897c3d951241fe78b8dc01a499611cead61e1c23dc6d75ee842407a6666f') ON CONFLICT DO NOTHING;
