INSERT INTO projects (id, reference_number, title, description, ai_summary, organization_id, category_id, source_id, country, state, budget_usd, currency, project_type, status, eligibility, official_link, contact_name, contact_email, contact_phone, tags, deadline, publication_date, source_hash) VALUES ('3298c577-bc9b-43df-8627-cf28084e4422', 'ocds-b5fd17-6f718135-9be9-4e4f-a625-2d4a9ab97ea3', 'Supply Of Mobilisation Packages, Furniture & White Goods', 'CRH intends to appoint suppliers capable of delivering a comprehensive, end-to-end accommodation inventory solution. This will include, but not be limited to, the sourcing and procurement of goods, appropriate storage, coordinated delivery, assembly and installation where required, decommissioning of existing items where applicable and the responsible disposal or recycling of waste packaging, furniture and white goods in accordance with environmental and regulatory standards. Suppliers will be required to deliver to CRH-designated locations in London and Wales and support the full lifecycle management of inventory.', NULL, 'c298cefe-d98e-43a7-b9a2-0c900da44efb', NULL, 'b0000000-0000-0000-0000-000000000002', 'United Kingdom', NULL, 1, 'GBP', 'Public Tender', 'Open', NULL, 'https://www.contractsfinder.service.gov.uk/Notice/0c280db5-def1-4b1c-bb4b-36e787f54b55', NULL, NULL, NULL, ARRAY['Furniture (incl. office furniture), furnishings, domestic appliances (excl. lighting) and cleaning products', 'UK', 'Contracts Finder'], '2026-08-31', '2026-07-08', '2a73bed29395e66d34780f41220fbe6f2ec5916511e7043984dc1f11cf7f6c21') ON CONFLICT DO NOTHING;
